import {CATEGORIES,COLORS,today,cents,validDate,validateTransaction,validateState,summarize,balances,parseEntry,parseReceipt,importTransactions,exportCSV,fingerprint} from './domain.js';
import {demoState,emptyState} from './seed.js';
import {icon,categoryIcon} from './icons.js';
import {recognizeReceipt,startVoice,stopVoice,aiExtract} from './capture.js';
import {createMoneyAssistant} from './assistant-ui.js';
import {createNavigationChrome} from './navigation.js';
import {formatMoney,formatNumber,formatCalendar} from './format.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navItems=[['overview','grid','Overview'],['transactions','list','Transactions'],['assistant','chat','Ask Pocket'],['budgets','chart','Budgets & goals'],['accounts','wallet','Accounts'],['settings','settings','Settings']];
let mode='demo',state,storageError='',storageMode='loading',remoteRevision=0,saving=false,switching=false,month=today().slice(0,7),view='overview',chartMode='cashflow',search='',filter='all',categoryFilter='all',pageIndex=0,toastTimer,capabilities={ai:false},captureTab='text',captureToken=0,modalFocus=null;
let captureRequest=null,captureDraft={text:'',voice:'',ai:false},modalSnapshot=null,summaryRows=null,summaryCache=new Map(),filterCache=null;
const draftSessions=new Map();
const navigationChrome=createNavigationChrome();
function drafts(){if(!draftSessions.has(mode))draftSessions.set(mode,{quick:'',settings:null});return draftSessions.get(mode);}
function monthlySummary(selectedMonth=month){if(summaryRows!==state.transactions){summaryRows=state.transactions;summaryCache.clear();}if(!summaryCache.has(selectedMonth)){if(summaryCache.size>=24)summaryCache.delete(summaryCache.keys().next().value);summaryCache.set(selectedMonth,summarize(state.transactions,selectedMonth));}return summaryCache.get(selectedMonth);}
// Resolve the signed-in user before opening any saved personal records.
state=demoState();
const storageKey=key=>capabilities.user?.id?'pocket-user-'+capabilities.user.id+'-'+key:'pocket-'+key;
const money=(n,decimals=2)=>formatMoney(n,state.settings.currency,decimals);
const number=formatNumber;
const monthName=m=>formatCalendar(m,'month');
const shortDate=d=>formatCalendar(d);
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||id;
const categoryColor=c=>COLORS[CATEGORIES.indexOf(c)]||COLORS[8];
const assistant=createMoneyAssistant({getState:()=>state,getContext:()=>({workspace:mode,month,today:today()}),getCapabilities:()=>capabilities,onEdit:id=>{const t=state.transactions.find(t=>t.id===id);if(t)review(t,id);else toast('This transaction is no longer in the workspace.');},onRefresh:()=>render()});
async function workspaceRequest(method,body){const response=await fetch('./api/workspace',{method,headers:{...(method==='PUT'?{'Content-Type':'application/json'}:{}),...(capabilities.user?{'X-Pocket-User':capabilities.user.id||'legacy'}:{})},body:body&&JSON.stringify(body),signal:AbortSignal.timeout(30000)});const result=await response.json();if(response.status===401){location.replace('/login'+location.hash);}if(!response.ok){const error=Error(result.error||'Could not reach the database.');error.status=response.status;throw error;}return result;}
async function openRemote(){const saved=await workspaceRequest('GET');if(saved.state){storageError='';return {state:validateState(saved.state),revision:saved.revision};}const local=capabilities.user?.legacy?localStorage.getItem('pocket-personal'):null;let state=emptyState();if(local)try{state=validateState(JSON.parse(local));}catch{throw Error('Your browser records could not be read. Keep a backup and restore a valid workspace before migrating.');}try{const result=await workspaceRequest('PUT',{revision:0,state});storageError='';return {state,revision:result.revision};}catch(error){if(error.status!==409)throw error;const latest=await workspaceRequest('GET');if(!latest.state)throw error;storageError='';return {state:validateState(latest.state),revision:latest.revision};}}
async function commit(update){if(saving||switching){formError(saving?'A save is already in progress. Try again.':'Wait for the workspace to open, then try again.');return false;}saving=true;try{if(storageMode==='loading'||storageMode==='error')throw Error('Storage is unavailable. Wait for the connection or reload.');const next=structuredClone(state);update(next);validateState(next);if(storageMode==='database'&&mode==='personal'){const result=await workspaceRequest('PUT',{revision:remoteRevision,state:next});remoteRevision=result.revision;}else localStorage.setItem(storageKey(mode),JSON.stringify(next));state=next;render();return true;}catch(e){const message=e.name==='QuotaExceededError'?'Device storage is full. Download a backup in Settings, then free space and try again.':e.message;formError('Could not save: '+message);return false;}finally{saving=false;}}
function toast(message,action){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${esc(message)}</span>${action?'<button id="toast-action">Undo</button>':''}`;$('#toast').classList.add('visible');if(action)$('#toast-action').onclick=()=>{action();$('#toast').classList.remove('visible');};toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),action?10000:4500);}
function focusSelector(el){if(!el||el===document.body)return null;if(el.id)return '#'+CSS.escape(el.id);for(const attr of ['data-chart','data-action','data-view'])if(el.hasAttribute(attr)){let selector=`[${attr}="${CSS.escape(el.getAttribute(attr))}"]`;for(const extra of ['data-id','data-category'])if(el.hasAttribute(extra))selector+=`[${extra}="${CSS.escape(el.getAttribute(extra))}"]`;if(el.closest('#mobile-navigation'))selector='#mobile-navigation '+selector;return selector;}const form=el.closest('form[id]');if(form&&el.name)return '#'+CSS.escape(form.id)+' [name="'+CSS.escape(el.name)+'"]';if(form&&el.type==='submit')return '#'+CSS.escape(form.id)+' [type=submit]';return null;}
function restoreModalFocus(){const target=(modalFocus&&$(modalFocus))||$('#page [data-action=capture]')||$('#main');target?.focus({preventScroll:true});modalFocus=null;}
function invalidateCapture(){captureToken++;captureRequest?.abort();captureRequest=null;stopVoice();assistant.stopListening();}
function closeModal(){const wasOpen=$('#modal').open;invalidateCapture();$('#modal').close();$('#modal-content').replaceChildren();modalSnapshot=null;if(wasOpen)restoreModalFocus();}
function modal(title,html){
 if(!$('#modal').open)modalFocus=focusSelector(document.activeElement);invalidateCapture();modalSnapshot=null;
 $('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${html}</div>`;
 const form=$('#modal form'),collection=({ 'transaction-form':'transactions','goal-form':'goals','account-form':'accounts','budget-form':'budgets'})[form?.id];
 if(collection)rememberEdit(collection,collection==='budgets'?form.dataset.category:form.dataset.id);
 if($('#capture-body'))hydrateCapture();
 if(!$('#modal').open)$('#modal').showModal();
}
function assertCurrentEdit(){if(!modalSnapshot)return;const {collection,id,value}=modalSnapshot;const current=collection==='budgets'?state.budgets[id]:state[collection].find(item=>item.id===id);if(JSON.stringify(current)!==value)throw Error('This record changed in another tab. Your draft is still here; copy any changes, then reopen the record to review its latest details.');}
function rememberEdit(collection,id){if(id)modalSnapshot={collection,id,value:JSON.stringify(collection==='budgets'?state.budgets[id]:state[collection].find(item=>item.id===id))};}
function refreshTransactionResults(){const focus=focusSelector(document.activeElement);$('#transaction-results').innerHTML=transactionResults();if(focus){const target=$(focus);if(target&&!target.disabled)target.focus({preventScroll:true});else $('#transaction-results .icon-button:not(:disabled)')?.focus({preventScroll:true});}}
const formError=e=>{const el=$('#form-error');if(el){el.textContent=e.message||e;el.setAttribute('role','alert');}else toast(e.message||e);};
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
function monthControl(){return `<div class="month-control"><button class="icon-button reverse" data-action="month-prev" aria-label="Previous month" ${month==='0001-01'?'disabled':''}>${icon('chevron',15)}</button><label class="sr-only" for="selected-month">Selected month</label><input id="selected-month" type="month" min="0001-01" max="9999-12" value="${month}"><button class="icon-button" data-action="month-next" aria-label="Next month" ${month==='9999-12'?'disabled':''}>${icon('chevron',15)}</button></div>`;}
function heading(title,subtitle,action=true){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-actions">${['overview','transactions','budgets','assistant'].includes(view)?monthControl():''}${action?`<button class="button" data-action="capture">${icon('plus',16)} Add transaction</button>`:''}</div></div>`;}
function banner(){return `${storageError?`<div class="notice error" role="alert">${esc(storageError)}</div>`:''}${mode==='demo'?`<div class="demo-banner">${icon('info')}<span>You’re exploring a sample workspace.</span><button class="text-button" data-action="start-personal">Make it yours ${icon('arrow',13)}</button></div>`:''}`;}
function render(){
 const focused=document.activeElement,focus=focusSelector(focused);
 const storageLabel=storageMode==='loading'?'Connecting...':storageMode==='error'?'Connection unavailable':storageMode==='database'&&mode==='personal'?'Saved to database':'Saved on this device';
 $('.local-status').innerHTML=`<i></i> ${storageLabel}`;
 const logScroll=$('#assistant-log')?.scrollTop;
 const validView=location.hash.slice(1);view=navItems.some(n=>n[0]===validView)?validView:'overview';
 document.body.classList.toggle('assistant-page',view==='assistant');
 if(!$('#navigation').children.length){$('#navigation').innerHTML=navItems.map(([id,i,title])=>`<button data-view="${id}" title="${title}" aria-label="${title}">${icon(i)}<span>${title}</span></button>`).join('');$('#mobile-navigation').innerHTML=navItems.filter(([id])=>id!=='settings').map(([id,i,title])=>`<button data-view="${id}" aria-label="${title}">${icon(i)}<span>${({transactions:'Activity',budgets:'Budgets',assistant:'Ask'})[id]||title}</span></button>`).join('');}
 document.querySelectorAll('#navigation button,#mobile-navigation button').forEach(button=>{const active=button.dataset.view===view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
 $('#breadcrumb').textContent=navItems.find(n=>n[0]===view)[2];const name=state.settings.name||'Your workspace';$('#profile-name').textContent=name;navigationChrome.update({name,mode,storageMode});document.querySelectorAll('.avatar').forEach(a=>a.textContent=(state.settings.name||'P')[0].toUpperCase());
 $('#page').innerHTML=({overview:overview,transactions:transactionsView,assistant:assistantView,budgets:budgetsView,accounts:accountsView,settings:settingsView}[view])();document.title=`${navItems.find(n=>n[0]===view)[2]} · Pocket`;
 if($('#quick-text'))$('#quick-text').value=drafts().quick;
 if($('#settings-form')&&drafts().settings)for(const [name,value] of Object.entries(drafts().settings))$('#settings-form').elements[name].value=value;
 if(logScroll!==undefined&&$('#assistant-log'))$('#assistant-log').scrollTop=logScroll;
 if(focus&&!focused.isConnected)$(focus)?.focus({preventScroll:true});
}
function overview(){
 const s=monthlySummary(),budget=Object.values(state.budgets).reduce((a,b)=>a+b,0),remaining=budget-s.expense;
 const rate=s.income>0?Math.round(s.net/s.income*100):null;
 const metrics=[['Money in',s.income,'up',`${s.rows.filter(t=>t.type==='income').length} income transactions`],['Money out',s.expense,'down',`${s.rows.filter(t=>t.type==='expense').length} expenses this month`],['Left in your budget',remaining,'wallet',remaining>=0?'A little breathing room':`${money(-remaining)} over budget`],['Net cashflow',s.net,'leaf',rate===null?'Add income to see your savings rate':`${rate}% of income left after expenses`]];
 return heading(state.settings.name?`A little clarity, ${state.settings.name}.`:'A little clarity for your money.','The big picture. And the little things that add up.')+banner()+`<button class="assistant-entry" data-view="assistant">${icon('chat',20)}<strong>A question about your money?</strong><span>Find it, add it up, make sense of it. Ask Pocket.</span>${icon('arrow',17)}</button><section class="metrics" aria-label="Monthly money summary">${metrics.map(([label,value,i,foot],idx)=>`<article class="metric ${idx===2?'primary':''}"><div class="metric-head"><span>${label}</span>${icon(i)}</div><div class="metric-value money"><span class="currency">${esc(state.settings.currency==='MYR'?'RM':state.settings.currency)}</span>${number(value)}</div><div class="metric-foot">${idx===3?icon('leaf',12):''}<span>${foot}</span></div></article>`).join('')}</section>
 <div class="dashboard-grid"><section class="panel panel-pad cashflow-panel"><div class="panel-header"><div><h2>Money in, money out</h2><p>Your last six months, at a glance.</p></div><div class="chart-tabs" aria-label="Chart view"><button data-chart="cashflow" class="${chartMode==='cashflow'?'active':''}" aria-pressed="${chartMode==='cashflow'}">Cashflow</button><button data-chart="spending" class="${chartMode==='spending'?'active':''}" aria-pressed="${chartMode==='spending'}">Spending</button></div></div>${cashflowChart()}<div class="chart-note">${icon('leaf')}${s.net>=0?`You kept ${money(s.net)} of this month’s income.`:`Expenses exceeded income by ${money(-s.net)} this month.`}</div></section>
 <section class="panel panel-pad allocation-panel"><div class="panel-header"><div><h2>Where it went</h2><p>A closer look at your spending.</p></div><span class="muted">${icon('chart',18)}</span></div>${allocation(s)}</section>
 <section class="panel transactions-panel"><div class="panel-header"><div><h2>The latest little things</h2><p>Your recent transactions.</p></div><button class="text-button" data-view="transactions">View all ${icon('arrow',14)}</button></div>${transactionTable(s.rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6),true)}<div class="table-foot"><span>${s.rows.length} transactions in ${monthName(month).split(' ')[0]}</span><span>All caught up ${icon('check',12)}</span></div></section>
 <section class="panel panel-pad capture-panel"><div class="panel-header"><div><h2>Just put it in Pocket.</h2><p>A sentence. A snap. A little less admin.</p></div><span class="capture-symbol">${icon('spark',21)}</span></div><form id="quick-form"><div class="quick-input"><label class="sr-only" for="quick-text">Describe your transaction</label><textarea id="quick-text" rows="2" placeholder="Coffee RM 12.90 at ZUS, paid with TNG" required maxlength="2000"></textarea><button class="button" type="submit" aria-label="Review transaction">${icon('arrow',17)}</button></div></form><div class="capture-options"><button data-action="voice">${icon('mic')} Say it</button><button data-action="camera">${icon('camera')} Snap it</button><button data-action="receipt">${icon('upload')} Upload</button></div><p class="capture-hint">${icon('shield')} You review the details before anything is saved.</p></section>
 <section class="panel panel-pad"><div class="panel-header"><div><h2>A plan that fits</h2><p>Your monthly budgets.</p></div><button class="text-button" data-view="budgets">Manage ${icon('arrow',13)}</button></div><div class="budget-mini">${Object.entries(state.budgets).filter(([k])=>['Food & drinks','Shopping','Transport'].includes(k)).map(([c,n])=>budgetLine(c,s.categories[c]||0,n)).join('')}</div><p class="budget-caption">${Object.entries(state.budgets).filter(([c,n])=>(s.categories[c]||0)<=n).length} of ${Object.keys(state.budgets).length} categories within budget.</p></section></div>
 <section class="panel goals-strip"><div class="goals-intro"><span>${icon('target',22)}</span><div><h2>For the things that matter.</h2><p>A little closer, every month.</p></div></div>${state.goals.length?state.goals.slice(0,2).map(goalCompact).join(''):`<div class="muted"><p>Your next adventure starts with a goal.</p></div><button class="button secondary" data-action="new-goal">${icon('plus',16)} Set a savings goal</button>`}</section>`;
}
function cashflowChart(){
 const months=[];for(let i=5;i>=0;i--){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-i);if(d.getUTCFullYear()<1)continue;const m=d.toISOString().slice(0,7);months.push({month:m,label:formatCalendar(m,'monthLabel'),...monthlySummary(m)});}
 const max=Math.max(100000,...months.flatMap(m=>chartMode==='spending'?[m.expense]:[m.income,m.expense]));const ceiling=Math.ceil(max/100000)*100000;
 return `<div class="chart-legend">${chartMode==='cashflow'?'<span><i class="dot"></i> Income</span>':''}<span><i class="dot" style="background:#c2d0b1"></i> Expenses</span><span>${esc(state.settings.currency)}</span></div><div class="cashflow-chart" role="img" aria-label="${esc(months.map(m=>`${m.label}: income ${money(m.income)}, expenses ${money(m.expense)}`).join('; '))}"><div class="chart-axis">${[1,.75,.5,.25,0].map(n=>`<span>${number(ceiling*n,0)}</span>`).join('')}</div><div class="chart-plot"><div class="grid-lines">${'<i></i>'.repeat(5)}</div>${months.map(m=>`<div class="bar-group ${m.month===month?'current':''}" title="${esc(`${monthName(m.month)}: ${money(m.income)} in, ${money(m.expense)} out`)}">${chartMode==='cashflow'?`<span class="bar" style="height:${m.income/ceiling*100}%"></span>`:''}<span class="bar expense" style="height:${m.expense/ceiling*100}%"></span><span class="bar-label">${m.label}</span></div>`).join('')}</div></div>`;
}
function allocation(s){
 const cats=Object.entries(s.categories).sort((a,b)=>b[1]-a[1]);if(!cats.length)return `<div class="empty">${icon('chart',35)}<h3>Your story starts here.</h3><p>Add an expense to see where your money goes.</p></div>`;
 const shown=cats.slice(0,4);if(cats.length>4)shown.push(['Everything else',cats.slice(4).reduce((a,[,v])=>a+v,0)]);let offset=0;
 const circles=shown.map(([c,n])=>{const pct=n/s.expense*100;const svg=`<circle cx="80" cy="80" r="62" fill="none" stroke="${categoryColor(c)}" stroke-width="19" pathLength="100" stroke-dasharray="${Math.max(0,pct-.8)} ${100-Math.max(0,pct-.8)}" stroke-dashoffset="${-offset}"/>`;offset+=pct;return svg;}).join('');
 return `<div class="allocation-layout"><div class="donut" role="img" aria-label="Total spending ${esc(money(s.expense))}. ${esc(shown.map(([c,n])=>`${c}: ${money(n)}`).join('; '))}"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="62" fill="none" stroke="#f1f3ed" stroke-width="19"/>${circles}</svg><div class="donut-center"><small>Total spent</small><strong class="money">${number(s.expense,0)}</strong><small>${esc(state.settings.currency)}</small></div></div></div><div class="category-list">${shown.map(([c,n])=>`<div class="category-line"><i class="dot" style="background:${categoryColor(c)}"></i><span class="category-name">${esc(c)}</span><strong class="money">${number(n,0)}</strong><span class="percentage">${Math.round(n/s.expense*100)}%</span></div>`).join('')}</div>`;
}
function budgetLine(c,spent,total){const pct=Math.round(spent/total*100);return `<div><div class="budget-line-head"><span>${esc(c)}</span><span><strong>${money(spent,0)}</strong> / ${number(total,0)}</span></div><div class="progress ${pct>100?'over':''}" role="progressbar" aria-label="${esc(c)} budget used" aria-valuenow="${Math.min(100,pct)}" aria-valuemin="0" aria-valuemax="100" aria-valuetext="${pct}% used"><span style="width:${Math.min(100,pct)}%"></span></div></div>`;}
function goalCompact(g){const pct=Math.round(g.saved/g.target*100);return `<div class="goal-compact"><div><h3>${esc(g.name)}</h3><button data-action="edit-goal" data-id="${esc(g.id)}" aria-label="Edit ${esc(g.name)}">${icon('edit',13)}</button></div><div class="progress" role="progressbar" aria-label="${esc(g.name)}" aria-valuenow="${Math.min(100,pct)}" aria-valuemin="0" aria-valuemax="100" aria-valuetext="${pct}% saved"><span style="width:${Math.min(100,pct)}%"></span></div><p><span>${money(g.saved,0)} <span class="muted">of ${money(g.target,0)}</span></span><strong>${pct}%</strong></p></div>`;}
function transactionTable(rows,compact=false){
 if(!rows.length)return `<div class="empty">${icon('receipt',36)}<h3>${search||filter!=='all'||categoryFilter!=='all'?'No matching transactions.':'A fresh page for your money.'}</h3><p>${search||filter!=='all'||categoryFilter!=='all'?'Try another search or clear your filters.':'Add your first expense, income, or transfer. We’ll take care of the big picture.'}</p><button class="button secondary" data-action="capture">${icon('plus',15)} Add transaction</button></div>`;
 return `<div class="table-scroll"><table class="transactions-table"><caption class="sr-only">${compact?'Recent':'Filtered'} transactions. Select a description to edit.</caption><thead><tr><th scope="col">Transaction</th><th scope="col" class="category-column">Category</th>${!compact?'<th scope="col" class="date-column">Date</th>':''}<th scope="col">Amount</th></tr></thead><tbody>${rows.map(t=>`<tr data-transaction="${esc(t.id)}"><td><div class="merchant-cell"><span class="category-icon" style="background:${categoryColor(t.category)}18;color:${categoryColor(t.category)==='#244e3f'?'#244e3f':'#5b6650'}">${icon(categoryIcon(t.category))}</span><span><button class="text-button" data-action="edit-transaction" data-id="${esc(t.id)}" style="color:inherit;text-align:left;padding:0"><strong>${esc(t.merchant)}</strong></button><small>${shortDate(t.date)} <span aria-hidden="true">·</span> ${esc(accountName(t.account))}${t.type==='transfer'?` → ${esc(accountName(t.toAccount))}`:''}</small></span></div></td><td class="category-column"><span class="category-tag">${esc(t.type==='transfer'?'Transfer':t.category)}</span></td>${!compact?`<td class="date-column muted">${shortDate(t.date)}</td>`:''}<td class="amount-cell ${t.type==='income'?'income':''}">${t.type==='income'?'+':t.type==='transfer'?'↔':'−'} ${money(t.amount)}</td></tr>`).join('')}</tbody></table></div>`;
}
function assistantView(){return heading('Ask Pocket.','A conversation with your money. Every answer grounded in your records.',false)+banner()+assistant.render();}
function filteredRows(){const key=JSON.stringify([month,filter,categoryFilter,search.toLowerCase()]);if(filterCache?.state===state&&filterCache.key===key)return filterCache.rows;const query=search.toLowerCase(),rows=monthlySummary().rows.filter(t=>(filter==='all'||t.type===filter)&&(categoryFilter==='all'||t.category===categoryFilter)&&(!query||`${t.merchant} ${t.category} ${t.note} ${accountName(t.account)}`.toLowerCase().includes(query))).sort((a,b)=>b.date.localeCompare(a.date));filterCache={state,key,rows};return rows;}
function transactionsView(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/20));pageIndex=Math.min(pageIndex,pages-1);return heading('Every little transaction.','Your money story, one entry at a time.')+banner()+`<div class="toolbar"><label class="search-field">${icon('search',18)}<span class="sr-only">Search transactions</span><input id="transaction-search" type="search" placeholder="Search a name, category, or note…" value="${esc(search)}"></label><label class="sr-only" for="type-filter">Filter by type</label><select id="type-filter">${[['all','All types'],['expense','Expenses'],['income','Income'],['transfer','Transfers']].map(([v,l])=>option(v,l,filter)).join('')}</select><label class="sr-only" for="category-filter">Filter by category</label><select id="category-filter">${option('all','All categories',categoryFilter)+CATEGORIES.map(c=>option(c,c,categoryFilter)).join('')}</select><button class="button secondary" data-action="import-csv">${icon('upload',15)} Import</button><button class="button secondary" data-action="export-csv">${icon('download',15)} Export</button></div><section class="panel full-table" id="transaction-results">${transactionResults(rows,pages)}</section>`;}
function transactionResults(rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/20))){pageIndex=Math.min(pageIndex,pages-1);return transactionTable(rows.slice(pageIndex*20,pageIndex*20+20))+`<div class="table-foot"><span>${rows.length} transactions · ${monthName(month)}</span><span><button class="icon-button reverse" data-action="page-prev" aria-label="Previous page" ${pageIndex===0?'disabled':''}>${icon('chevron',13)}</button> ${pageIndex+1} / ${pages} <button class="icon-button" data-action="page-next" aria-label="Next page" ${pageIndex>=pages-1?'disabled':''}>${icon('chevron',13)}</button></span></div>`;}
function budgetsView(){const s=monthlySummary(),budget=Object.values(state.budgets).reduce((a,b)=>a+b,0);return heading('Make room for what matters.','A flexible plan for everyday spending. A little progress toward bigger things.')+banner()+`<div class="insight">${icon('leaf',19)}<span>${money(budget-s.expense)} ${budget>=s.expense?'left in':'over'} your ${money(budget)} monthly budget.</span></div><div class="section-heading"><h2>Monthly budgets</h2>${CATEGORIES.slice(0,9).some(c=>!Object.hasOwn(state.budgets,c))?`<button class="button secondary" data-action="new-budget">${icon('plus',16)} Add a budget</button>`:''}</div><section class="budget-grid" aria-label="Category budgets">${Object.entries(state.budgets).map(([c,n])=>{const spent=s.categories[c]||0,pct=Math.round(spent/n*100);return `<article class="panel budget-card"><div class="budget-card-head"><span class="category-icon">${icon(categoryIcon(c))}</span><h3>${esc(c)}</h3><button class="icon-button" data-action="edit-budget" data-category="${esc(c)}" aria-label="Edit ${esc(c)} budget">${icon('edit',15)}</button></div><div class="budget-numbers money"><strong>${money(spent,0)}</strong><span> / ${number(n,0)}</span></div><div class="progress ${pct>100?'over':''}" role="progressbar" aria-label="${esc(c)} budget used" aria-valuenow="${Math.min(pct,100)}" aria-valuemin="0" aria-valuemax="100" aria-valuetext="${pct}% used"><span style="width:${Math.min(pct,100)}%"></span></div><div class="budget-card-foot"><span class="${pct>100?'over-text':''}">${money(Math.abs(n-spent),0)} ${pct>100?'over budget':'left'}</span><span>${pct}% used</span></div></article>`;}).join('')}${Object.keys(state.budgets).length?'':'<div class="panel empty full-width"><h3>A plan of your own.</h3><p>Add a monthly budget for a category you want to track.</p></div>'}</section><div class="section-heading"><h2>Your next chapters</h2><button class="button secondary" data-action="new-goal">${icon('plus',16)} Add a goal</button></div><p class="muted" style="font-size:11px;margin-bottom:16px">Goal progress is tracked separately. Updating it won’t move money between accounts.</p><div class="budget-grid">${state.goals.length?state.goals.map(g=>`<article class="panel panel-pad">${goalCompact(g)}</article>`).join(''):'<div class="panel empty full-width"><h3>What are you saving for?</h3><p>A buffer, a trip, or something entirely yours.</p></div>'}</div>`;}
function accountsView(){const b=balances(state.accounts,state.transactions),total=Object.values(b).reduce((a,v)=>a+v,0);return heading('All your pockets.','A clear view of the money you’ve recorded across your accounts.',false)+banner()+`<div class="section-heading" style="margin-top:0"><span class="muted">Recorded balance <strong class="money" style="color:var(--ink);margin-left:12px;font-size:25px">${money(total)}</strong></span><button class="button" data-action="new-account">${icon('plus',16)} Add account</button></div><section class="account-grid">${state.accounts.map(a=>`<article class="panel account-card"><div class="panel-header"><div><h2>${esc(a.name)}</h2><p>${esc(a.kind||'Account')} · Manually tracked</p></div>${icon('wallet',23)}</div><div class="account-amount money">${money(b[a.id])}</div><div class="account-bottom"><span class="muted" style="font-size:10px">${state.transactions.filter(t=>t.account===a.id||t.toAccount===a.id).length} transactions</span><button class="text-button" data-action="edit-account" data-id="${esc(a.id)}">Edit account ${icon('edit',13)}</button></div></article>`).join('')}</section><section class="panel connection-panel">${icon('link',32)}<div><h2>Your statements, without the busywork.</h2><p>Import bank or e-wallet transactions from a CSV. You’ll review the entries and duplicates before saving. Direct bank and e-wallet syncing is not connected.</p></div><button class="button secondary" data-action="import-csv">${icon('upload',16)} Import statement</button></section><p class="muted" style="font-size:11px;margin-top:17px">Balances include the opening balance and all recorded transactions, across all dates. Negative balances can represent debt. They are not live bank balances.</p>`;}
function settingsView(){return heading('Your Pocket, your way.','A few simple preferences. And complete control of your records.',false)+banner()+`<div class="settings-grid"><section class="panel settings-panel"><h2>A little more you.</h2><p>Make yourself at home.</p><form id="settings-form"><label class="form-label">What should we call you?<input name="name" type="text" maxlength="60" value="${esc(state.settings.name)}" placeholder="Your first name"></label><label class="form-label">Workspace currency<select name="currency">${['MYR','USD','SGD','EUR','GBP'].map(c=>option(c,c,state.settings.currency)).join('')}</select><span class="input-hint">Changing currency relabels amounts; it does not convert them.</span></label><button class="button" type="submit">Save preferences</button></form></section><section class="panel settings-panel"><h2>Capture, your way.</h2><p>Quick entry is always available. Other methods depend on your browser and setup.</p><div class="status-row"><span>Text & automatic categories</span><span class="pill">Ready</span></div><div class="status-row"><span>Receipt OCR <small>· first use needs internet</small></span><span class="pill">On device</span></div><div class="status-row"><span>Voice dictation</span><span class="pill">${('SpeechRecognition'in window||'webkitSpeechRecognition'in window)?'Available':'Browser not supported'}</span></div><div class="status-row"><span>AI extraction</span><span class="pill">${capabilities.ai?'Configured':'Not configured'}</span></div><p style="margin-top:16px;font-size:10px">Optional AI uses a server-side Gemini API key. When enabled for a capture, only that text or receipt is sent to Google. Voice recognition may use your browser vendor’s service.</p></section><section class="panel settings-panel"><h2>Your data stays yours.</h2><p>${storageMode==='database'&&mode==='personal'?'Your personal records are saved in PostgreSQL in your signed-in account. Download backups regularly.':'Records are saved in this browser. Back them up regularly - clearing browser storage removes them.'} Backups contain your financial records in plain text.</p><div class="settings-actions"><button class="button" data-action="backup">${icon('download',15)} Download backup</button><button class="button secondary" data-action="restore">${icon('upload',15)} Restore backup</button><button class="button secondary" data-action="export-all">Export all CSV</button>${storageMode==='database'?'<button class="button secondary" data-action="sign-out">Sign out</button>':''}</div><div class="notice" style="margin-top:21px">${icon('shield',16)} No bank credentials are collected. ${storageMode==='database'&&mode==='personal'?'Your personal workspace is available across devices after signing in to your account.':'Browser storage is local and not synced between devices.'}</div></section><section class="panel settings-panel"><h2>A safe place to explore.</h2><p>Your personal and sample workspaces are stored separately. Try things out without touching your own records.</p><div class="status-row"><span>Current workspace</span><strong>${mode==='demo'?'Sample data':'Personal'}</strong></div><div class="settings-actions"><button class="button secondary" data-action="${mode==='demo'?'start-personal':'switch-demo'}">${mode==='demo'?'Open personal workspace':'Explore sample workspace'} ${icon('arrow',15)}</button></div></section></div>`;}

function capture(tab='text',preserve=false){if(!preserve)captureDraft={text:'',voice:'',ai:false};captureTab=tab;modal('A little less admin.',`<div class="capture-tabs" role="tablist" aria-label="Capture method">${[['text','edit','Type it'],['voice','mic','Say it'],['receipt','receipt','Scan it']].map(([t,i,l])=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-capture-tab="${t}">${icon(i,16)}${l}</button>`).join('')}</div><div id="capture-body">${tab==='text'?`<form id="text-capture-form"><label class="form-label">What happened?<textarea name="text" id="capture-text" placeholder="Paid RM 24 for lunch at Village Park with cash" rows="4" maxlength="2000" required></textarea></label><p class="input-hint" style="margin:9px 0 18px">Include an amount, a place, and optionally an account or “yesterday”.</p>${aiCheckbox()}<div class="form-error" id="form-error"></div><div class="modal-actions"><button class="button secondary" type="button" data-action="manual">Enter manually</button><button class="button" type="submit">Review details ${icon('arrow',16)}</button></div></form>`:tab==='voice'?`<div class="voice-state"><button class="voice-button" id="voice-start" aria-label="Start dictation">${icon('mic',28)}</button><h3 id="voice-label">Just say what you spent.</h3><p id="voice-message">Try “Lunch RM 18.50 at the café, paid with cash.” Your browser may send audio to its speech service.</p></div><label class="form-label">Your transcript<textarea id="voice-transcript" rows="3" placeholder="Your words will appear here. You can edit them."></textarea></label><div class="form-error" id="form-error"></div><div class="modal-actions"><button class="button secondary" data-action="manual">Enter manually</button><button class="button" id="voice-review">Review details ${icon('arrow',16)}</button></div>`:`<button class="dropzone" data-action="choose-receipt">${icon('receipt',36)}<strong>One receipt. All the little details.</strong><span>Choose a photo, or drop one here.<br>JPG, PNG, WebP · up to 10 MB</span><span class="button secondary small">Choose receipt ${icon('upload',14)}</span></button><div class="settings-actions"><button class="button secondary" data-action="choose-camera">${icon('camera',16)} Take a photo</button><button class="button ghost" data-action="manual">Enter manually</button></div><p class="input-hint" style="margin:13px 0">OCR reads your image on this device. Its language files download on first use. Use a clear, upright English receipt.</p>${aiCheckbox()}<div id="receipt-progress"></div><div class="form-error" id="form-error"></div>`}</div>`);}
function hydrateCapture(){if($('#capture-text'))$('#capture-text').value=captureDraft.text;if($('#voice-transcript'))$('#voice-transcript').value=captureDraft.voice;if($('#use-ai'))$('#use-ai').checked=captureDraft.ai;}
function aiCheckbox(){return capabilities.ai?'<label class="check-label"><input id="use-ai" type="checkbox">Use AI extraction for this entry. Sends this text or receipt to Google; you review the result.</label>':'';}
function review(draft={},editId=null,origin=''){
 const t={merchant:'',amount:null,date:today(),category:'Other',type:'expense',account:state.accounts[0].id,note:'',...draft};if(!state.accounts.some(a=>a.id===t.account))t.account=state.accounts[0].id;
 const duplicated=!editId&&t.amount&&state.transactions.some(x=>fingerprint(x)===fingerprint(t));
 modal(editId?'The little details.':'Looks right? Make it yours.',`<p>${editId?'Update this transaction. Your balances and charts will follow.':'Check the details below. Nothing is saved until you say so.'}</p>${duplicated?'<div class="notice warning" style="margin-top:12px">A matching transaction already exists. Check before saving another copy.</div>':''}<form id="transaction-form" data-id="${esc(editId||'')}" data-source="${esc(t.source||'Manual')}"><div class="segment">${['expense','income','transfer'].map(type=>`<label><input type="radio" name="type" value="${type}" ${t.type===type?'checked':''}>${type[0].toUpperCase()+type.slice(1)}</label>`).join('')}</div><div class="form-grid"><label class="form-label wide">Description<input name="merchant" type="text" maxlength="200" required value="${esc(t.merchant)}" placeholder="Where did your money go?"></label><label class="form-label">Amount (${esc(state.settings.currency)})<input name="amount" type="number" inputmode="decimal" min="0.01" max="999999999.99" step="0.01" required value="${t.amount?(t.amount/100).toFixed(2):''}" placeholder="0.00"></label><label class="form-label">Date<input name="date" type="date" required value="${esc(t.date)}"></label><label class="form-label">Category<select name="category">${CATEGORIES.map(c=>option(c,c,t.category)).join('')}</select></label><label class="form-label">From / account<select name="account">${state.accounts.map(a=>option(a.id,a.name,t.account)).join('')}</select></label><label class="form-label wide" id="destination-label" ${t.type!=='transfer'?'hidden style="display:none"':''}>Transfer to<select name="toAccount">${state.accounts.map(a=>option(a.id,a.name,t.toAccount||state.accounts.find(a=>a.id!==t.account)?.id)).join('')}</select></label><label class="form-label wide">Note <span class="input-hint">Optional</span><textarea name="note" maxlength="1000" rows="2">${esc(t.note)}</textarea></label></div>${t.extractedText?`<details class="details-data"><summary>View extracted receipt text</summary><pre class="preview-data">${esc(t.extractedText)}</pre></details>`:''}<div class="form-error" id="form-error"></div><div class="modal-actions">${editId?`<button class="icon-button delete-button" type="button" data-action="delete-transaction" data-id="${esc(editId)}" aria-label="Delete transaction">${icon('trash',18)}</button>`:''}<button type="button" class="button secondary" data-action="close">Cancel</button><button type="submit" class="button">${icon('check',16)} ${editId?'Save changes':'Save transaction'}</button></div></form>`);
 $('#transaction-form').dataset.origin=origin;
}
function editBudget(category){
 const available=CATEGORIES.slice(0,9).filter(c=>!Object.hasOwn(state.budgets,c));
 if(!category&&!available.length){toast('Every spending category already has a budget. Edit a limit to change it.');return;}
 modal(category?'A budget with breathing room.':'Make a little room.',`<p>Monthly limits repeat every month. Updating a limit changes the plan for all months.</p><form id="budget-form" data-category="${esc(category||'')}"><div class="form-grid">${category?'':`<label class="form-label wide">Category<select name="category" required>${available.map(c=>option(c,c)).join('')}</select></label>`}<label class="form-label wide">${category?esc(category)+' - ':''}Monthly limit (${esc(state.settings.currency)})<input type="number" name="amount" min="0.01" max="999999999.99" step="0.01" required value="${category?(state.budgets[category]/100).toFixed(2):''}"></label></div><div id="form-error" class="form-error"></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button" type="submit">Save budget</button></div></form>`);
}
function editGoal(id){const g=state.goals.find(g=>g.id===id)||{name:'',target:null,saved:0};modal(id?'A little closer.':'What are you saving for?',`<p>Track progress toward something that matters. This won’t change account balances.</p><form id="goal-form" data-id="${esc(id||'')}"><div class="form-grid"><label class="form-label wide">Goal name<input type="text" name="name" maxlength="100" value="${esc(g.name)}" placeholder="My emergency fund" required></label><label class="form-label">Target (${esc(state.settings.currency)})<input type="number" name="target" min="0.01" step="0.01" value="${g.target?g.target/100:''}" required></label><label class="form-label">Already saved<input type="number" name="saved" min="0" step="0.01" value="${g.saved/100}" required></label></div><div class="form-error" id="form-error"></div><div class="modal-actions">${id?`<button type="button" class="icon-button delete-button" data-action="delete-goal" data-id="${esc(id)}" aria-label="Delete goal">${icon('trash')}</button>`:''}<button class="button secondary" type="button" data-action="close">Cancel</button><button class="button" type="submit">Save goal</button></div></form>`);}
function editAccount(id){const a=state.accounts.find(a=>a.id===id)||{name:'',kind:'Bank',opening:0};modal(id?'Your account details.':'Another pocket for your money.',`<p>The opening balance is your balance before the transactions recorded here. Use a negative amount for debt.</p><form id="account-form" data-id="${esc(id||'')}"><div class="form-grid"><label class="form-label wide">Account name<input type="text" name="name" maxlength="80" required value="${esc(a.name)}" placeholder="e.g. Maybank savings"></label><label class="form-label">Type<select name="kind">${['Bank','E-wallet','Cash','Credit card','Loan','Other'].map(k=>option(k,k,a.kind)).join('')}</select></label><label class="form-label">Opening balance<input type="number" name="opening" step="0.01" max="999999999.99" min="-999999999.99" required value="${a.opening/100}"></label></div><div class="form-error" id="form-error"></div><div class="modal-actions"><button class="button secondary" type="button" data-action="close">Cancel</button><button class="button" type="submit">Save account</button></div></form>`);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function switchWorkspace(nextMode){if(saving){toast('Wait for your save to finish, then switch workspaces.');return;}if(switching)return;switching=true;try{if(storageMode==='loading'||storageMode==='error')throw Error('Storage is unavailable. Reload and try again.');let next,revision;if(nextMode==='personal'&&storageMode==='database'){const remote=await openRemote();next=remote.state;revision=remote.revision;}else{const stored=localStorage.getItem(storageKey(nextMode));next=stored?validateState(JSON.parse(stored)):(nextMode==='demo'?demoState():emptyState());}localStorage.setItem(storageKey('mode'),nextMode);state=next;if(revision!==undefined)remoteRevision=revision;mode=nextMode;if(nextMode!=='personal'||storageMode!=='database')storageError='';search='';filter=categoryFilter='all';month=today().slice(0,7);closeModal();location.hash='overview';render();toast(nextMode==='personal'?'Your own Pocket. Ready when you are.':'Sample workspace opened.');}catch(e){toast('Could not open workspace: '+e.message);}finally{switching=false;}}
function importInfo(){modal('Bring your statements along.',`<p>Import a CSV from your bank or e-wallet. Match these columns first; amounts use the workspace currency.</p><div class="notice" style="margin-top:15px"><strong>Required:</strong> date (YYYY-MM-DD), merchant or description, amount.<br><strong>Optional:</strong> type (expense/income/transfer), category, account, toAccount, note.<br>Without a type, rows are expenses. Income must be marked explicitly.</div><p style="margin-top:15px;font-size:11px">Account IDs: ${state.accounts.map(a=>`<strong>${esc(a.id)}</strong> (${esc(a.name)})`).join(', ')}. Missing accounts default to ${esc(state.accounts[0].name)}. Matching date, amount, description and account rows are skipped.</p><div class="modal-actions"><button class="button secondary" data-action="csv-template">Download template</button><button class="button" data-action="choose-csv">${icon('upload',16)} Choose CSV</button></div>`);}
async function receiptFile(file){
 if(!file)return;if(file.size>10*1024*1024){formError('Choose an image smaller than 10 MB.');return;}if(!/^image\/(jpeg|png|webp)$/.test(file.type)){formError('Use a JPG, PNG or WebP photo.');return;}
 if(captureTab!=='receipt'||!$('#receipt-progress'))capture('receipt');const useAI=$('#use-ai')?.checked;const token=++captureToken;const update=message=>{if(token===captureToken&&$('#receipt-progress'))$('#receipt-progress').innerHTML=`<div class="processing"><span class="spinner"></span><span>${esc(message)}</span></div>`;};
 captureRequest?.abort();const request=new AbortController();captureRequest=request;
 update('Reading your receipt…');try{const result=useAI?await aiExtract({file,signal:request.signal}):parseReceipt(await recognizeReceipt(file,update,request.signal));if(token!==captureToken)return;review({...result,source:useAI?'AI receipt':'Receipt'});}catch(e){if(token!==captureToken)return;$('#receipt-progress').innerHTML='';formError(e);}finally{if(captureRequest===request)captureRequest=null;}
}

document.addEventListener('click',async e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({block:'start'});return;}
 const el=e.target.closest('button,[data-transaction]');if(!el)return;
 if(el.disabled)return;
 if(el.dataset.view){if(view!==el.dataset.view)location.hash=el.dataset.view;return;}
 if(el.dataset.chart){if(chartMode===el.dataset.chart)return;chartMode=el.dataset.chart;document.querySelectorAll('[data-chart]').forEach(button=>{const active=button.dataset.chart===chartMode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});const panel=$('.cashflow-panel');panel.querySelector('.chart-legend').remove();panel.querySelector('.cashflow-chart').outerHTML=cashflowChart();return;}
 if(el.dataset.captureTab){capture(el.dataset.captureTab,true);return;}
 const action=el.dataset.action,id=el.dataset.id;
 if(action==='sign-out'){
  if(saving){toast('Wait for your save to finish, then sign out.');return;}
  el.disabled=true;
  try{const response=await fetch('/api/auth/logout',{method:'POST',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Could not sign out. Please try again.');document.body.replaceChildren();location.replace('/login');}
  catch(error){el.disabled=false;toast(error.message);}return;
 }
 const actions={capture:()=>capture(),'manual':()=>review(),'voice':()=>capture('voice'),'receipt':()=>capture('receipt'),'camera':()=>{capture('receipt');$('#camera-file').click();},'choose-camera':()=>$('#camera-file').click(),'choose-receipt':()=>$('#receipt-file').click(),close:closeModal,'month-prev':()=>changeMonth(-1),'month-next':()=>changeMonth(1),'start-personal':()=>switchWorkspace('personal'),'switch-demo':()=>switchWorkspace('demo'),'edit-transaction':()=>review(state.transactions.find(t=>t.id===id),id),'edit-budget':()=>editBudget(el.dataset.category),'new-budget':()=>editBudget(),'new-goal':()=>editGoal(),'edit-goal':()=>editGoal(id),'new-account':()=>editAccount(),'edit-account':()=>editAccount(id),'import-csv':importInfo,'choose-csv':()=>$('#csv-file').click(),'csv-template':()=>download('pocket-import-template.csv',`date,merchant,amount,type,category,account\n${today()},Example lunch,18.50,expense,Food & drinks,${state.accounts[0].id}`,'text/csv'),'export-csv':()=>download(`pocket-${month}.csv`,exportCSV(filteredRows()),'text/csv'),'export-all':()=>download('pocket-all-transactions.csv',exportCSV(state.transactions),'text/csv'),backup:()=>download(`pocket-${mode}-${today()}.json`,JSON.stringify(state,null,2)),restore:()=>$('#backup-file').click(),'page-prev':()=>{pageIndex=Math.max(0,pageIndex-1);refreshTransactionResults();},'page-next':()=>{pageIndex++;refreshTransactionResults();},'delete-transaction':async()=>{const old=state.transactions.find(t=>t.id===id);if(await commit(s=>s.transactions=s.transactions.filter(t=>t.id!==id))){closeModal();toast('Transaction deleted.',()=>commit(s=>s.transactions.push(old)));}},'delete-goal':async()=>{const old=state.goals.find(g=>g.id===id);if(await commit(s=>s.goals=s.goals.filter(g=>g.id!==id))){closeModal();toast('Goal deleted.',()=>commit(s=>s.goals.push(old)));}}};
 if(actions[action]){try{if(action==='delete-transaction'||action==='delete-goal')assertCurrentEdit();await actions[action]();}catch(error){formError(error);}return;}
 if(el.id==='voice-start'){
 if(el.classList.contains('listening')){stopVoice();el.classList.remove('listening');$('#voice-label').textContent='Dictation stopped.';return;}
 try{const token=captureToken;startVoice(text=>{if(token!==captureToken)return;captureDraft.voice=text;$('#voice-transcript').value=text;},message=>{if(token!==captureToken)return;$('#voice-start')?.classList.remove('listening');if($('#voice-label'))$('#voice-label').textContent=message;});el.classList.add('listening');$('#voice-label').textContent='Listening. Take your time.';}catch(err){formError(err);}return;}
 if(el.id==='voice-review'){const text=$('#voice-transcript').value.trim();if(!text){formError('Say something first, or type your transaction below.');return;}review(parseEntry(text));return;}
 if(el.dataset.transaction)review(state.transactions.find(t=>t.id===el.dataset.transaction),el.dataset.transaction);
});
function refreshMonthView(){if(view!=='assistant'){render();return;}$('#selected-month').value=month;$('[data-action=month-prev]').disabled=month==='0001-01';$('[data-action=month-next]').disabled=month==='9999-12';if($('[data-assistant-month]'))$('[data-assistant-month]').textContent=formatCalendar(month,'monthShort');}
function changeMonth(delta){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);if(d.getUTCFullYear()<1||d.getUTCFullYear()>9999)return;month=d.toISOString().slice(0,7);pageIndex=0;refreshMonthView();}
function trackDraft(target){if(target.id==='quick-text')drafts().quick=target.value;if(target.closest('#settings-form'))drafts().settings=Object.fromEntries(new FormData($('#settings-form')));if(target.id==='capture-text')captureDraft.text=target.value;if(target.id==='voice-transcript')captureDraft.voice=target.value;if(target.id==='use-ai')captureDraft.ai=target.checked;}
document.addEventListener('change',e=>{trackDraft(e.target);if(e.target.id==='selected-month'){if(validDate(e.target.value+'-01')&&e.target.value>='0001-01'&&e.target.value<='9999-12'){month=e.target.value;pageIndex=0;refreshMonthView();}else e.target.value=month;}if(e.target.id==='type-filter'){filter=e.target.value;pageIndex=0;refreshTransactionResults();}if(e.target.id==='category-filter'){categoryFilter=e.target.value;pageIndex=0;refreshTransactionResults();}if(e.target.name==='type'&&$('#destination-label')){$('#destination-label').hidden=e.target.value!=='transfer';$('#destination-label').style.display=e.target.value==='transfer'?'flex':'none';}});
document.addEventListener('input',e=>{trackDraft(e.target);if(e.target.id==='transaction-search'){search=e.target.value;pageIndex=0;refreshTransactionResults();}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-capture-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['text','voice','receipt'],current=tabs.indexOf(e.target.dataset.captureTab),index=e.key==='Home'?0:e.key==='End'?2:(current+(e.key==='ArrowRight'?1:2))%3;capture(tabs[index],true);document.querySelector(`[data-capture-tab="${tabs[index]}"]`)?.focus();});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['quick-form','text-capture-form','transaction-form','budget-form','goal-form','account-form','settings-form'].includes(form.id))return;e.preventDefault();
 if(!form.isConnected||form.dataset.busy==='true'||(form.closest('#modal')&&!$('#modal').open))return;
 const token=captureToken,isModal=!!form.closest('#modal'),data=Object.fromEntries(new FormData(form));form.dataset.busy='true';
 try{
 if(isModal)assertCurrentEdit();
 if(form.id==='quick-form'){review(parseEntry($('#quick-text').value),null,'quick');return;}
 if(form.id==='text-capture-form'){const useAI=$('#use-ai')?.checked;if(useAI){const button=form.querySelector('[type=submit]'),request=new AbortController();captureRequest=request;button.disabled=true;button.textContent='Reading…';try{const r=await aiExtract({text:data.text,signal:request.signal});if(token===captureToken)review({...r,source:'AI text'});}finally{if(captureRequest===request)captureRequest=null;if(button.isConnected){button.disabled=false;button.textContent='Review details';}}}else review(parseEntry(data.text));return;}
 if(form.id==='transaction-form'){const t=validateTransaction({...data,id:form.dataset.id||crypto.randomUUID(),amount:cents(data.amount),source:form.dataset.source});if(t.type!=='transfer')delete t.toAccount;if(await commit(s=>{const i=s.transactions.findIndex(x=>x.id===t.id);if(i<0)s.transactions.unshift(t);else s.transactions[i]=t;})){if(form.dataset.origin==='quick'){drafts().quick='';if($('#quick-text'))$('#quick-text').value='';}closeModal();toast(form.dataset.id?'Transaction updated.':'A little more clarity. Transaction saved.');}return;}
 if(form.id==='budget-form'){const amount=cents(data.amount),category=form.dataset.category||data.category;if(!CATEGORIES.slice(0,9).includes(category))throw Error('Choose a spending category.');if(await commit(s=>{if(!form.dataset.category&&Object.hasOwn(s.budgets,category))throw Error('This category already has a budget. Reopen it to review the current limit.');s.budgets[category]=amount;})){closeModal();toast('Budget saved.');}return;}
 if(form.id==='goal-form'){const g={id:form.dataset.id||crypto.randomUUID(),name:data.name.trim(),target:cents(data.target),saved:Number(data.saved)===0?0:cents(data.saved)};if(await commit(s=>{const i=s.goals.findIndex(x=>x.id===g.id);if(i<0)s.goals.push(g);else s.goals[i]=g;})){closeModal();toast('Goal saved. Every little bit counts.');}return;}
 if(form.id==='account-form'){const raw=data.opening.trim(),opening=Number(raw)===0?0:(raw.startsWith('-')?-cents(raw.slice(1)):cents(raw));const a={id:form.dataset.id||'account-'+crypto.randomUUID(),name:data.name.trim(),kind:data.kind,opening};if(await commit(s=>{const i=s.accounts.findIndex(x=>x.id===a.id);if(i<0)s.accounts.push(a);else s.accounts[i]=a;})){closeModal();toast('Account saved.');}return;}
 if(form.id==='settings-form'){if(await commit(s=>s.settings={name:data.name.trim(),currency:data.currency})){drafts().settings=null;toast('A little more you. Preferences saved.');}}
 }catch(err){if(!isModal||(token===captureToken&&form.isConnected))formError(err);}finally{form.dataset.busy='false';}
});
$('#receipt-file').addEventListener('change',e=>{receiptFile(e.target.files[0]);e.target.value='';});$('#camera-file').addEventListener('change',e=>{receiptFile(e.target.files[0]);e.target.value='';});
document.addEventListener('dragover',e=>{if(e.target.closest('.dropzone'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.target.closest('.dropzone')){e.preventDefault();receiptFile(e.dataTransfer.files[0]);}});
function readingFile(title){modal(title,'<div class="processing" role="status"><span class="spinner"></span><span>Reading your file…</span></div><div class="modal-actions"><button class="button secondary" data-action="close">Cancel</button></div>');return captureToken;}
$('#csv-file').addEventListener('change',async e=>{
 const file=e.target.files[0];e.target.value='';if(!file)return;const token=readingFile('Opening your statement.');
 try{
  if(file.size>5*1024*1024)throw Error('Choose a CSV smaller than 5 MB.');const text=await file.text();if(token!==captureToken)return;
  const result=importTransactions(text,state.transactions,state.accounts.map(a=>a.id));
  modal('A quick check before they’re in.',`<p>${result.rows.length} new transactions · ${result.duplicates} duplicates skipped · ${result.errors.length} rows need attention.</p>${result.errors.length?`<details class="details-data" open><summary>Rows not imported</summary><div class="notice warning">${result.errors.slice(0,20).map(esc).join('<br>')}</div></details>`:''}<div class="import-preview"><ul>${result.rows.slice(0,100).map(t=>`<li><span>${esc(t.merchant)} <small class="muted">${t.date}</small></span><strong>${money(t.amount)}</strong></li>`).join('')}</ul></div>${result.rows.length>100?'<p class="input-hint">Showing the first 100 entries.</p>':''}<div class="form-error" id="form-error"></div><div class="modal-actions"><button class="button secondary" data-action="close">Cancel</button><button id="confirm-import" class="button" ${!result.rows.length?'disabled':''}>Import ${result.rows.length} transactions</button></div>`);
  const confirmation=captureToken;$('#confirm-import').onclick=async()=>{if(confirmation!==captureToken)return;if(await commit(s=>{const keys=new Set(s.transactions.map(fingerprint));for(const t of result.rows)if(!keys.has(fingerprint(t))){keys.add(fingerprint(t));s.transactions.push(t);}})){closeModal();toast('Statement imported. Duplicates skipped.');}};
 }catch(err){if(token===captureToken){closeModal();toast(err.message);}}
});
$('#backup-file').addEventListener('change',async e=>{
 const file=e.target.files[0];e.target.value='';if(!file)return;const token=readingFile('Opening your backup.');
 try{
  if(file.size>20*1024*1024)throw Error('Backup is too large.');const text=await file.text();if(token!==captureToken)return;const next=validateState(JSON.parse(text));
  modal('Restore this Pocket?',`<p>This replaces the current <strong>${mode==='demo'?'sample':'personal'}</strong> workspace with ${next.transactions.length} transactions and ${next.accounts.length} accounts. Download a backup first if you want to keep the current records.</p><div id="form-error" class="form-error"></div><div class="modal-actions"><button class="button secondary" data-action="backup">Back up current data</button><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button" id="confirm-restore">Restore backup</button></div>`);
  const confirmation=captureToken;$('#confirm-restore').onclick=async()=>{if(confirmation!==captureToken)return;if(await commit(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next);})){drafts().settings=null;drafts().quick='';closeModal();render();toast('Backup restored.');}};
 }catch(err){if(token===captureToken){closeModal();toast('Could not restore: '+err.message);}}
});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#help-button').innerHTML=icon('shield',18);$('#help-button').onclick=()=>{location.hash='settings';};$('#side-leaf').innerHTML=icon('leaf',34);
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(storageMode==='database'&&mode==='personal')return;if(e.key===storageKey(mode)&&e.newValue){try{state=validateState(JSON.parse(e.newValue));render();toast('Updated from another tab.');}catch{toast('Another tab saved unreadable data. Your current view is unchanged.');}}});
$('#page').innerHTML='<div class="panel panel-pad" role="status">Opening Pocket...</div>';
(async()=>{try{const response=await fetch('./api/capabilities',{signal:AbortSignal.timeout(10000)});if(response.status===401){location.replace('/login'+location.hash);return;}if(!response.ok)throw Error('Could not check storage.');capabilities=await response.json();storageMode=capabilities.storage==='database'?'database':'browser';const selected=localStorage.getItem(storageKey('mode'));mode=selected==='personal'?'personal':selected==='demo'?'demo':storageMode==='database'?'personal':'demo';if(storageMode!=='database'||mode==='demo'){const saved=localStorage.getItem(storageKey(mode));state=saved?validateState(JSON.parse(saved)):(mode==='demo'?demoState():emptyState());}if(storageMode==='database'&&mode==='personal'){const remote=await openRemote();state=remote.state;remoteRevision=remote.revision;}render();}catch(error){storageMode='error';storageError='Could not connect to Pocket storage. '+error.message+' Saves are paused.';render();}})();

async function checkAccount(){if(storageMode!=='database')return;try{const response=await fetch('/api/capabilities',{signal:AbortSignal.timeout(10000)});if(response.status===401){location.replace('/login'+location.hash);return;}if(response.ok){const current=await response.json();if(current.user?.id!==capabilities.user?.id)location.reload();}}catch{}}
window.addEventListener('pageshow',event=>{if(event.persisted)checkAccount();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkAccount();});
